import numpy as np, itertools
from analysis import *

PHI_DECK, PHI_CONN, PHI_BA, PHI_WA, PHI_T = 0.60, 0.75, 0.75, 0.75, 0.90
H_IN = 28*12.0
SHOWN = [('S01','X',+1,'base',False,'final'),('S02','X',-1,'base',False,'final'),
         ('S03','Y',+1,'base',False,'final'),('S04','Y',-1,'base',False,'final'),
         ('S05','X',+1,'base',True,'final'),('S06','Y',-1,'base',True,'final'),
         ('S07','X',+1,'future',False,'final'),('S08','Y',+1,'future',False,'final'),
         ('S09','X',-1,'future',True,'final'),('S10','Y',-1,'future',True,'final'),
         ('S11','X',+1,'erection',False,'erection'),('S12','Y',-1,'erection',False,'erection')]
def all_cases():
    cs=list(SHOWN)
    k=0
    for d,sg,mc,orth in itertools.product('XY',(+1,-1),('base','future'),(False,True)):
        key=(d,sg,mc,orth,'final')
        if any((c[1],c[2],c[3],c[4],c[5])==key for c in cs): continue
        k+=1; cs.append((f'H{k:02d}',d,sg,mc,orth,'final'))
    for d,sg,orth in itertools.product('XY',(+1,-1),(False,True)):
        key=(d,sg,'erection',orth,'erection')
        if any((c[1],c[2],c[3],c[4],c[5])==key for c in cs): continue
        k+=1; cs.append((f'H{k:02d}',d,sg,'erection',orth,'erection'))
    return cs

def member_capacity(mem):
    name,A,Fy,rate=MEMBERS[mem]
    return PHI_T*Fy*A

class Evaluator:
    def __init__(self, design):
        self.d=design; self.M=Model(design); self.cache={}
    def primary(self, d, sg, mc, stage):
        key=(d,sg,mc,stage)
        if key in self.cache: return self.cache[key]
        r1=self.M.fe_case(d,sg,mc,stage,1.0)
        ax=ax_factor(*r1['rigid']['dres'])
        r=self.M.fe_case(d,sg,mc,stage,ax) if ax>1.0 else r1
        fl=flexible_case(self.M,d,mc,stage)
        out={'ax':ax,'semirigid':r['semirigid'],'rigid':r['rigid'],'flexible':fl}
        self.cache[key]=out
        return out
    @staticmethod
    def demands(res, ideal):
        """extract demand dict (absolute values) from one idealisation result"""
        q=res[ideal]
        if q is None: return None
        D={}
        for w in 'SNWE':
            D[('wall',w)]=abs(q['wall'][w]+q['own'].get(w,0.0))
        for z,v in q['zone'].items(): D[('zone',z)]=abs(v)
        for k,v in q['seg'].items(): D[('segR',)+k]=abs(v)
        if ideal=='flexible':
            D[('chordflex',)]=q['chordmax']
            for w,(xs,C) in q['coll'].items(): D[('collflex',w)]=float(np.abs(C).max())
        else:
            for ln,v in q['lineN'].items(): D[('line',ln)]=v
            D[('disp',)]=q['dmax']; D[('dperp',)]=q['dperp']
        for w,v in q['own'].items(): D[('own',w)]=v
        return D
    def case_demands(self, case):
        cid,d,sg,mc,orth,stage=case
        P=self.primary(d,sg,mc,stage)
        out={'ax':P['ax']}
        dd='Y' if d=='X' else 'X'
        C=self.primary(dd,sg,mc,stage) if orth else None
        for ideal in ('flexible','rigid','semirigid'):
            A=self.demands(P,ideal)
            if A is None: out[ideal]=None; continue
            if orth:
                B=self.demands(C,ideal)
                if B is not None:
                    keys=set(A)|set(B)
                    A={k:A.get(k,0.0)+0.3*B.get(k,0.0) for k in keys}
            out[ideal]=A
        return out

def seg_force_total(model, w, sid, segR, own_w):
    """segment force incl. share of own inertia (by stiffness)"""
    ks=model.kseg[w]; tot=sum(ks.values())
    return segR+own_w*ks[sid]/tot

def tiedown_per_unit(model, w, sid):
    """max tie-down force per kip segment force, and max joint shear per kip"""
    r=model.sa[w][sid]
    T=0.0
    for p in r['panel']:
        Mb=abs(p['Mb_b'])
        T=max(T,Mb/(0.8*p['L']*12.0)+abs(p['N']))
    J=max([abs(j) for j in r['joint_shear']],default=0.0)
    return T,J

def check(design, cases=None, verbose=False):
    if cases is None: cases=all_cases()
    E=Evaluator(design); M=E.M
    env={}   # key -> (value, case, ideal)
    rep={}
    for c in cases:
        cd=E.case_demands(c)
        rep[c[0]]=cd
        for ideal in ('flexible','rigid','semirigid'):
            D=cd[ideal]
            if D is None: continue
            for k,v in D.items():
                # segment total force
                if k[0]=='segR':
                    w,sid=k[1],k[2]
                    own=D.get(('own',w),0.0)
                    v=seg_force_total(M,w,sid,v,own)
                    k=('seg',w,sid)
                if k not in env or v>env[k][0]: env[k]=(v,c[0],ideal)
    return E,env,rep

def utilizations(design, env, E):
    M=E.M; U={}
    for z in ZONES:
        cap=PHI_DECK*DECK[design['deck'][z]][0]
        v=env.get(('zone',z),(0,))[0]
        U[('zone',z)]=v/cap
    for w in 'SNWE':
        wd=design['walls'][w]
        tcap=PHI_BA*BA[wd['ba']][0]
        jcap=PHI_CONN*JC[wd['jc']][0]*wd['n'] if wd['jc']!='JC0' else None
        for s in SEGS[w]:
            F=env.get(('seg',w,s['id']),(0,))[0]
            T,J=tiedown_per_unit(M,w,s['id'])
            U[('tiedown',w,s['id'])]=F*T/tcap
            if jcap: U[('joint',w,s['id'])]=F*J/jcap
    # lines
    for ln,mem in design['lines'].items():
        if mem in (None,'C0'): continue
        cap=member_capacity(mem)
        d,at,f,t,kind=LINES[ln]
        vals=[env.get(('line',ln),(0,))[0]*OM0]
        # flexible: chord lines carry beam chord force; drag/chord lines on walls carry collector
        wl={('X',0):'S',('X',180):'N',('Y',0):'W',('Y',240):'E'}.get((d,at))
        if kind in ('chord',):
            vals.append(env.get(('chordflex',),(0,))[0])
        if wl and kind in ('drag','chord'):
            vals.append(env.get(('collflex',wl),(0,))[0]*OM0)
        U[('line',ln)]=max(vals)/cap
    dmax=env.get(('disp',),(0,))[0]*CD/IE
    U[('deflection',)]=dmax/4.0
    return U

def cost(design):
    c={}
    areas={}
    for z,(x0,y0,x1,y1) in ZONES.items():
        a=(x1-x0)*(y1-y0)
        for _,a0,b0,a1,b1 in ROOF_OPENINGS:
            ox=max(0,min(x1,a1)-max(x0,a0)); oy=max(0,min(y1,b1)-max(y0,b0))
            a-=ox*oy
        areas[z]=a
    c['deck']=sum(areas[z]*DECK[design['deck'][z]][2] for z in ZONES)
    c['lines']=sum((LINES[ln][3]-LINES[ln][2])*MEMBERS[m][3] for ln,m in design['lines'].items() if m not in (None,'C0'))
    npan={w:sum(len(s['panels']) for s in SEGS[w]) for w in 'SNWE'}
    njt={w:sum(len(s['panels'])-1 for s in SEGS[w]) for w in 'SNWE'}
    c['connectors']=sum(njt[w]*design['walls'][w]['n']*JC[design['walls'][w]['jc']][2] for w in 'SNWE' if design['walls'][w]['jc']!='JC0')
    c['tiedowns']=sum(npan[w]*BA[design['walls'][w]['ba']][1] for w in 'SNWE')
    c['anchors']=sum(WALL_LEN[w]/design['walls'][w]['wa_s']*WA[design['walls'][w]['wa']][1] for w in 'SNWE')
    c['sfrs']=sum(npan.values())*SFRS_PREMIUM[design['sfrs']]
    c['total']=sum(c.values())
    return c,areas,npan,njt
